INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (9999,'ZemplerBank','$source = \"Zempler Bank\"\n$features = \"REVERSE_ORDER\"\n$periodBufferDays = 5\n\n// Get account name (the account holder name shown at top left)\n$accountName = get line starting \"Stephen Walton\" => get text\n\n// Get account number\n$accountNumber = get line starting \"Account number:\" => skip words 2 => get text\n\n// Delete address block on right side to avoid interference with balances\n@addrTop = get line starting \"Address\" => top\n@addrBottom = get line starting \"Currency:\" => bottom\ndelete text in box @addrTop @addrBottom page.middleX page.right\n\n// Get period from/to\n@periodLine = get line starting \"From\" => take last words 7\n$periodFrom = take words @periodLine 3 => get date \"dd/MM/yyyy\"\n$periodTo = take last words @periodLine 3 => get date \"dd/MM/yyyy\"\n\n// Get opening and closing balances\n$openingBalance = get line starting \"Opening Balance:\" => skip words 2 => get decimal\n$closingBalance = get line starting \"Closing Balance:\" => skip words 2 => get decimal\n\n// Discard footer\nget line starting \"Zempler Bank Ltd is registered\" => top => ignore footer below\n\n// Get start and end of table\ngo to page 1\n@transactionsTop = get line starting \"Date Card ending in\" => bottom => get line below\n\ngo to last page\n@transactionsBottom = get line above 0\n\n// Discard repeating page headers\nget last line starting \"Date Card ending in\" => bottom => ignore header above\n\ndelete all lines starting \"Date Card ending in\"\ndelete all lines starting \"Zempler Bank Ltd is registered\"\ndelete all lines starting \"Zempler Bank provides credit\"\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 90 170 430 500 page.right => describe table false \"*Date[dd/MM/yyyy]\" - Details **#Amount #Balance\n',UTC_TIMESTAMP(),0);
INSERT INTO `digitalpdf$documentidentification` (`Id`,`Name`,`TitlePattern`,`AuthorPattern`,`CreatorPattern`,`ProducerPattern`,`Version`,`PageCount`,`SignatureInfo`,`ContainsText`,`ExcludesText`,`ScriptId`,`VerificationRuleSetId`,`ModificationTimeUtc`,`IsDeleted`) VALUES (9999,'ZemplerBank',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'[\"Zempler Bank\",\"Opening Balance:\",\"Closing Balance:\",\"Card ending in\"]',NULL,9999,4,UTC_TIMESTAMP(),0);